public struct FfiConverterTypeMeshEngine: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = MeshEngine

    public static func lift(_ handle: UInt64) throws -> MeshEngine {
        return MeshEngine(unsafeFromHandle: handle)
    }

    public static func lower(_ value: MeshEngine) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MeshEngine {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: MeshEngine, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


