/**
 * Raw advertising data (the core parses it).
 */

public enum FfiAdvData: Equatable, Hashable {
    
    /**
     * Android scan-response service data after `MESH_SVC`, or the raw AD sequence.
     */
    case serviceData(bytes: Data
    )
    /**
     * iPhone foreground local name.
     */
    case localName(name: String
    )
    /**
     * Only the service UUID (iPhone in background).
     */
    case uuidOnly





}

#if compiler(>=6)
extension FfiAdvData: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiAdvData: FfiConverterRustBuffer {
    typealias SwiftType = FfiAdvData

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiAdvData {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .serviceData(bytes: try FfiConverterData.read(from: &buf)
        )
        
        case 2: return .localName(name: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .uuidOnly
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiAdvData, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .serviceData(bytes):
            writeInt(&buf, Int32(1))
            FfiConverterData.write(bytes, into: &buf)
            
        
        case let .localName(name):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(name, into: &buf)
            
        
        case .uuidOnly:
            writeInt(&buf, Int32(3))
        
        }
