/**
 * Radio decisions executed by the platform (§3.2).
 */

public enum FfiRadioCommand: Equatable, Hashable {
    
    case setDiscovery(mode: FfiDiscoveryMode, adv: FfiAdvPayload?, scan: FfiScanIntensity
    )
    /**
     * New 16-byte HELLO value.
     */
    case setHello(bytes: Data
    )
    case connect(discId: UInt32
    )
    case openLink(discId: UInt32, via: FfiOpenVia
    )
    case abort(discId: UInt32, ignoreS: UInt16
    )
    /**
     * `reason` is the CLOSE/REJECT reason byte already sent in band, if any.
     */
    case close(link: UInt32, reason: UInt8?
    )
    case setLinkParams(link: UInt32, priority: FfiLinkPriority
    )
    case armReconnect(peerRef: UInt32, untilS: UInt16
    )
    case awareUpgrade(peer: UInt16, op: UInt8
    )
    case tunnelOpen(peer: UInt16
    )





}

#if compiler(>=6)
extension FfiRadioCommand: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiRadioCommand: FfiConverterRustBuffer {
    typealias SwiftType = FfiRadioCommand

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiRadioCommand {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .setDiscovery(mode: try FfiConverterTypeFfiDiscoveryMode.read(from: &buf), adv: try FfiConverterOptionTypeFfiAdvPayload.read(from: &buf), scan: try FfiConverterTypeFfiScanIntensity.read(from: &buf)
        )
        
        case 2: return .setHello(bytes: try FfiConverterData.read(from: &buf)
        )
        
        case 3: return .connect(discId: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 4: return .openLink(discId: try FfiConverterUInt32.read(from: &buf), via: try FfiConverterTypeFfiOpenVia.read(from: &buf)
        )
        
        case 5: return .abort(discId: try FfiConverterUInt32.read(from: &buf), ignoreS: try FfiConverterUInt16.read(from: &buf)
        )
        
        case 6: return .close(link: try FfiConverterUInt32.read(from: &buf), reason: try FfiConverterOptionUInt8.read(from: &buf)
        )
        
        case 7: return .setLinkParams(link: try FfiConverterUInt32.read(from: &buf), priority: try FfiConverterTypeFfiLinkPriority.read(from: &buf)
        )
        
        case 8: return .armReconnect(peerRef: try FfiConverterUInt32.read(from: &buf), untilS: try FfiConverterUInt16.read(from: &buf)
        )
        
        case 9: return .awareUpgrade(peer: try FfiConverterUInt16.read(from: &buf), op: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 10: return .tunnelOpen(peer: try FfiConverterUInt16.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiRadioCommand, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .setDiscovery(mode,adv,scan):
            writeInt(&buf, Int32(1))
            FfiConverterTypeFfiDiscoveryMode.write(mode, into: &buf)
            FfiConverterOptionTypeFfiAdvPayload.write(adv, into: &buf)
            FfiConverterTypeFfiScanIntensity.write(scan, into: &buf)
            
        
        case let .setHello(bytes):
            writeInt(&buf, Int32(2))
            FfiConverterData.write(bytes, into: &buf)
            
        
        case let .connect(discId):
            writeInt(&buf, Int32(3))
            FfiConverterUInt32.write(discId, into: &buf)
            
        
        case let .openLink(discId,via):
            writeInt(&buf, Int32(4))
            FfiConverterUInt32.write(discId, into: &buf)
            FfiConverterTypeFfiOpenVia.write(via, into: &buf)
            
        
        case let .abort(discId,ignoreS):
            writeInt(&buf, Int32(5))
            FfiConverterUInt32.write(discId, into: &buf)
            FfiConverterUInt16.write(ignoreS, into: &buf)
            
        
        case let .close(link,reason):
            writeInt(&buf, Int32(6))
            FfiConverterUInt32.write(link, into: &buf)
            FfiConverterOptionUInt8.write(reason, into: &buf)
            
        
        case let .setLinkParams(link,priority):
            writeInt(&buf, Int32(7))
            FfiConverterUInt32.write(link, into: &buf)
            FfiConverterTypeFfiLinkPriority.write(priority, into: &buf)
            
        
        case let .armReconnect(peerRef,untilS):
            writeInt(&buf, Int32(8))
            FfiConverterUInt32.write(peerRef, into: &buf)
            FfiConverterUInt16.write(untilS, into: &buf)
            
        
        case let .awareUpgrade(peer,op):
            writeInt(&buf, Int32(9))
            FfiConverterUInt16.write(peer, into: &buf)
            FfiConverterUInt8.write(op, into: &buf)
            
        
        case let .tunnelOpen(peer):
            writeInt(&buf, Int32(10))
            FfiConverterUInt16.write(peer, into: &buf)
            
        }
    }
}


